const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const esc = (v='') => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api = async (url, options={}) => { const res=await fetch(url,{credentials:'same-origin',headers:{'content-type':'application/json','x-demo-user':guestId(),'x-nexora-profile':localStorage.getItem('nexora_profile')||'',...(options.headers||{})},...options});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||'Something went wrong.');return data; };
function guestId(){let v=localStorage.getItem('nexora_guest');if(!v){v='guest-'+crypto.randomUUID();localStorage.setItem('nexora_guest',v)}return v}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
