function icon(name){const p={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',fire:'<path d="M12 22c4.3 0 7-2.8 7-6.6 0-2.7-1.4-5.4-4.5-8.4.1 2.2-1.1 3.2-2.2 3.6.5-3.8-1.5-6.5-4.2-8.6C8.8 6.6 5 9.7 5 15.3 5 19.3 7.8 22 12 22Z"/><path d="M12 19c1.8 0 3-1.2 3-2.9 0-1.2-.7-2.4-2.1-3.8-.1 1.1-.7 1.8-1.5 2.1-.1-1.1-.7-1.9-1.5-2.6.1 2-1 3-1 4.3C8.9 17.8 10.1 19 12 19Z"/>',star:'<path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.4-5.7-3-5.7 3 1.1-6.4-4.6-4.5 6.4-.9z"/>',grid:'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="13" y="3" width="8" height="8" rx="1.5"/><rect x="3" y="13" width="8" height="8" rx="1.5"/><rect x="13" y="13" width="8" height="8" rx="1.5"/>',tv:'<rect x="3" y="6" width="18" height="13" rx="2"/><path d="m8 3 4 3 4-3M9 22h6"/>',bookmark:'<path d="M6 4.8A1.8 1.8 0 0 1 7.8 3h8.4A1.8 1.8 0 0 1 18 4.8V21l-6-3.8L6 21z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>'};return `<svg class="nav-svg" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${p[name]||p.star}</svg>`}
