function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div class="footer-about">${brand()}<p>Nexora is an independent home for movies, series and new stories from across Africa and beyond.</p></div><div class="footer-col"><h4>Explore</h4><a href="/app/discover">Movies</a><a href="/app/discover?type=TV+Show">TV Series</a><a href="/app/genres">Genres</a><a href="/app/watchlist">My List</a><a href="/app/player/demo">Player preview</a></div><div class="footer-col"><h4>Nexora</h4><a href="/#features">Our features</a><a href="/testimonials">Testimonials</a><a href="/plans">Plans</a><a href="mailto:hello@nexora.app">Contact</a></div><div class="footer-col"><h4>Your account</h4><a href="/signin">Sign in</a><a href="/signup">Create account</a><a href="/testimonials#share">Share your story</a></div><div class="footer-newsletter"><h4>Stay in the loop</h4><p>Get updates when new Nexora stories are ready to explore.</p><form class="newsletter-form" data-form="newsletter"><input type="email" name="email" required placeholder="Enter your email" aria-label="Email address"><button class="button" type="submit">Subscribe</button></form><div class="form-feedback" aria-live="polite"></div></div></div><div class="footer-bottom"><span>© 2026 Nexora. All rights reserved.</span><div class="socials"><a href="https://instagram.com" aria-label="Instagram">◎</a><a href="https://youtube.com" aria-label="YouTube">▷</a><a href="mailto:hello@nexora.app" aria-label="Email">✉</a></div></div></div></footer>`}
function posterCard(m,compact=false){const figmaArt=String(m.poster||'').startsWith('/assets/home-posters/');return `<article class="poster-card ${figmaArt?'figma-poster':''}" data-open="${esc(m.id)}" tabindex="0" role="link" aria-label="View ${esc(m.title)} details"><div class="poster-art" style="--art:${m.art};background-image:${figmaArt?`url('${esc(m.poster)}')`:`linear-gradient(0deg,#09111f30,transparent 75%),url('${esc(m.poster)}'),${m.art}`}" ${figmaArt?'data-figma-art="true"':''}>${figmaArt?'':`<span class="poster-top">${esc(m.type==='TV Show'?'SERIES':'MOVIE')}</span><button class="watch-add" data-watch="${esc(m.id)}" aria-label="Add ${esc(m.title)} to watchlist">＋</button><span class="poster-title-art">${esc(m.title)}</span>`}<button class="poster-trailer" data-play="${esc(m.id)}" data-trailer-title="${esc(m.title)}" aria-label="Play ${esc(m.title)}">▶</button></div><div class="poster-info"><h3 class="poster-name">${esc(m.title)}</h3><div class="poster-meta"><span>${esc(m.year)}${figmaArt?'':` · ${esc(m.genre)}`}</span>${figmaArt?'':`<span class="rating">★ ${esc(m.rating)}</span>`}</div></div></article>`}
const avatarPhotos=["https://randomuser.me/api/portraits/women/44.jpg","https://randomuser.me/api/portraits/men/32.jpg","https://randomuser.me/api/portraits/women/65.jpg","https://randomuser.me/api/portraits/men/75.jpg","https://randomuser.me/api/portraits/women/12.jpg","https://randomuser.me/api/portraits/men/46.jpg"];
function quoteCard(t){const initials=t.initials||String(t.name).split(/\s+/).map(x=>x[0]).join('').slice(0,2);const seed=[...String(t.name)].reduce((n,c)=>n+c.charCodeAt(0),0);const photo=avatarPhotos[seed%avatarPhotos.length];return `<article class="quote-card"><div class="quote-stars" aria-label="${t.rating||5} out of 5 stars">${'★'.repeat(t.rating||5)}</div><blockquote>“${esc(t.quote)}”</blockquote><div class="quote-person"><img class="avatar" src="${photo}" alt="Portrait of ${esc(t.name)}" loading="lazy"><span class="person-meta"><strong>${esc(t.name)}</strong><small>${esc(t.role||'Nexora viewer')}</small></span></div></article>`}
async function getMovies(params={}){try{return (await api('/api/movies?'+new URLSearchParams(params))).movies}catch{return movieFallback.filter(m=>(!params.genre||m.genre===params.genre)&&(!params.platform||(m.platform||'').toLowerCase()===params.platform.toLowerCase())&&(!params.type||params.type==='All'||m.type===params.type)&&(!params.q||`${m.title} ${m.genre} ${m.platform||''}`.toLowerCase().includes(params.q.toLowerCase()))).sort(params.sort==='rating'?(a,b)=>Number(b.rating)-Number(a.rating):()=>0)}}
async function getTestimonials(){try{return (await api('/api/testimonials')).testimonials}catch{return testimonialFallback}}
